<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Blend Generator','description'=>'Blend two colors and get the resulting CSS color.','url'=>'https://smarttoolz.in/tools/color-blend-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Color Blend Generator</h1><p>Mix two colors with an adjustable ratio.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="a" type="color" value="#5b43ff"><input id="b" type="color" value="#ff4365"><label>Blend %<input id="x" type="range" min="0" max="100" value="50"></label><p id="o"></p><div id="p" style="height:100px;border-radius:12px"></div></div></section></main><script>function go(){let q=(z)=>{z=z.slice(1);return[0,2,4].map(i=>parseInt(z.slice(i,i+2),16))},A=q(a.value),B=q(b.value),f=+x.value/100,R=A.map((v,i)=>Math.round(v+(B[i]-v)*f));o.textContent=`rgb(${R.join(',')})`;p.style.background=o.textContent}a.oninput=b.oninput=x.oninput=go;go()</script><?php smarttoolz_tool_page_end(); ?>